using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;using UnityEngine.Video;
public static class VoyagePresentationCheck {
 static Stack<IEnumerator> stack;static string report;static int errors;
 public static void Begin(){if(!EditorApplication.isPlaying)throw new Exception("Start menu Play Mode first");report="Menu, intro, portraits and fresh ship visits\n";errors=0;EditorApplication.isPaused=false;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();stack=new();stack.Push(Run());Application.logMessageReceived+=Log;EditorApplication.update+=Tick;}
 static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception)errors++;}
 static void Tick(){EditorApplication.QueuePlayerLoopUpdate();try{if(stack.Count==0){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;return;}var e=stack.Peek();if(!e.MoveNext()){stack.Pop();return;}if(e.Current is IEnumerator child)stack.Push(child);else if(e.Current is AsyncOperation op)stack.Push(WaitOp(op));}catch(Exception e){report+="FAIL "+e+"\n";Save();EditorApplication.update-=Tick;Application.logMessageReceived-=Log;}}
 static void Save()=>File.WriteAllText("Tools/MenuPortraitUpdate/verification.txt",report);
 static void Check(bool ok,string text){report+=(ok?"PASS ":"FAIL ")+text+"\n";Save();if(!ok)throw new Exception(text);}
 static IEnumerator Wait(float seconds){double t=EditorApplication.timeSinceStartup+seconds;while(EditorApplication.timeSinceStartup<t)yield return null;}
 static IEnumerator WaitOp(AsyncOperation op){while(!op.isDone)yield return null;}
 static IEnumerator Talk(ShipVisitDialogue d){double end=EditorApplication.timeSinceStartup+8;while(!d.ReadyForGameplay&&EditorApplication.timeSinceStartup<end){if(d.UI&&d.UI.Active)d.UI.Advance();yield return null;}Check(d.ReadyForGameplay,"dialogue ends and releases controls");}
 static IEnumerator Run(){
 typeof(VoyageMainMenu).GetField("introPlayed",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,false);Time.timeScale=1;yield return SceneManager.LoadSceneAsync("Assets/Scenes/MainMenu.unity");yield return Wait(.3f);var menu=UnityEngine.Object.FindFirstObjectByType<VoyageMainMenu>();Check(menu&&menu.teamIntro,"Andronova clip assigned");var video=UnityEngine.Object.FindFirstObjectByType<VideoPlayer>();double deadline=EditorApplication.timeSinceStartup+10;while(video&&!video.isPrepared&&EditorApplication.timeSinceStartup<deadline)yield return null;yield return Wait(.4f);Check(video&&video.isPrepared&&video.frame>=0,"Andronova video actually decodes and plays");ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/intro.png");Check(!menu.GetComponentsInChildren<Button>(true).Any(b=>b.name=="Skip intro"),"intro has no skip button");video.time=System.Math.Max(0,video.length-.3);yield return Wait(3);Check(menu.GetComponentsInChildren<Image>().Any(i=>i.name=="Game logo"&&i.sprite==Resources.Load<Sprite>("Voyage/logo")),"provided game logo appears in menu");ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/menu.png");
 yield return SceneManager.LoadSceneAsync(StorySceneJourney.ShipPath);yield return Wait(.3f);var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();var ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();var water=ship.GetComponent<ShipWaterPurification>();var dialogue=ship.GetComponent<ShipVisitDialogue>();Check(dialogue&&dialogue.UI.Active&&dialogue.UI.SpeakerPortrait==Resources.Load<Sprite>("Voyage/harbor_officer"),"harbor officer portrait in entry textbox");yield return Wait(.2f);var bodyText=dialogue.UI.GetComponentsInChildren<Text>().First(t=>t.name=="Single sentence");Check(Time.timeScale==0&&bodyText.text.Length>0,"textbox types while ship gameplay is paused");ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/dialogue.png");dialogue.UI.Advance();yield return null;dialogue.UI.Advance();yield return null;Check(dialogue.UI.SpeakerPortrait==Resources.Load<Sprite>("Voyage/captain"),"captain portrait in captain textbox");yield return Talk(dialogue);Check(ship.enabled&&ship.GetComponent<ShipWeapons>().enabled&&Time.timeScale==1,"native control and weapons restored after text");float baseSpeed=ship.maxSpeed;float baseHealth=ship.GetComponent<PlayerHealth>().maxHealth;ui.currentLevel=7;ui.currentXP=3.25f;ship.maxSpeed+=9;ship.currentEnergy=7;ship.GetComponent<PlayerHealth>().SetMaxHealth(150,true);ship.GetComponent<PlayerHealth>().TakeDamage(40);water.RestoreProgress(.8f);Bullet.bonusDamage=9;var snapshot=ShipVisitSnapshot.Capture(ship.gameObject,ui,water);
 yield return SceneManager.LoadSceneAsync(StorySceneJourney.ShipPath);yield return Wait(.3f);ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();water=ship.GetComponent<ShipWaterPurification>();snapshot.Restore(ship.gameObject,ui,water);Check(water.NormalizedProgress==0&&water.percentage.text=="%0","new visit starts purification at zero");Check(ship.currentEnergy==ship.maxEnergy&&ship.GetComponent<PlayerHealth>().CurrentHealth==ship.GetComponent<PlayerHealth>().MaxHealth,"new visit starts with full energy and health");Check(ui.currentLevel==7&&ui.currentXP==3.25f&&ui.nextLevelXP==Mathf.Round(ui.baseXP*Mathf.Pow(ui.xpGrowthMultiplier,7)),"only level and XP progression persist with correct threshold");Check(ship.maxSpeed==baseSpeed&&ship.GetComponent<PlayerHealth>().maxHealth==baseHealth&&Bullet.bonusDamage==0,"other ship upgrades use fresh authored defaults");yield return Talk(ship.GetComponent<ShipVisitDialogue>());ship.enabled=false;var rb=ship.GetComponent<Rigidbody2D>();rb.rotation=0;rb.linearVelocity=Vector2.up*5;yield return Wait(.2f);Check(water.NormalizedProgress>0,"existing forward-travel purification still works");float p=water.NormalizedProgress;Time.timeScale=0;yield return Wait(.2f);Check(water.NormalizedProgress==p,"pause still freezes purification");Time.timeScale=1;
 yield return SceneManager.LoadSceneAsync("Assets/Scenes/MainMenu.unity");yield return Wait(.2f);Check(!UnityEngine.Object.FindFirstObjectByType<VideoPlayer>(),"intro does not replay on same-session menu return");menu=UnityEngine.Object.FindFirstObjectByType<VoyageMainMenu>();menu.GetComponentsInChildren<Button>().First(b=>b.name=="New game").onClick.Invoke();yield return Wait(1);while(StorySceneJourney.Instance.IsTransitioning)yield return null;Check(SceneManager.GetActiveScene().path==StorySceneJourney.UnderwaterPath&&StorySceneJourney.Instance.Stage==JourneyStage.FirstUnderwater,"menu New Game opens first underwater chapter");Check(errors==0,"no runtime errors during current verification");report+="Scene reloads and runtime-only state mutations used for verification; no authored combat tuning changed.\n";Save();}
}
